//SMFDUMP  JOB (ACCT),'SMF DUMP',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IFASMFDP
//SYSPRINT DD SYSOUT=*
//DUMPIN   DD DSN=SYS1.MANX,DISP=SHR
//DUMPOUT  DD DSN=SMF.DUMP.DATA,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,
//            SPACE=(CYL,(100,50),RLSE),
//            DCB=(RECFM=VBS,LRECL=32760,BLKSIZE=0)
//SYSIN    DD *
  INDD(DUMPIN,OPTIONS(DUMP))
  OUTDD(DUMPOUT,TYPE(0:255))
/*

//COPYJOB  JOB (ACCT),'COPY DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=INPUT.DATASET,DISP=SHR
//SYSUT2   DD DSN=OUTPUT.DATASET,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,
//            SPACE=(TRK,(100,50),RLSE),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=27920)
//SYSIN    DD DUMMY

//ALLOCDS  JOB (ACCT),'ALLOCATE',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//NEWDS    DD DSN=MY.NEW.DATASET,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,
//            SPACE=(CYL,(10,5),RLSE),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=27920)

//BACKUP   JOB (ACCT),'DFDSS BACKUP',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=ADRDSSU
//SYSPRINT DD SYSOUT=*
//DASD     DD UNIT=3390,VOL=SER=VOL001,DISP=SHR
//TAPE     DD DSN=BACKUP.DATA,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=CART
//SYSIN    DD *
  DUMP DATASET(INCLUDE(USER.**)) -
       OUTDD(TAPE) -
       COMPRESS -
       ALLDATA(*) ALLEXCP
/*

//LINKEDIT JOB (ACCT),'LINK EDIT',CLASS=A,MSGCLASS=X
//LKED     EXEC PGM=IEWL,PARM='LIST,XREF,LET,MAP'
//SYSPRINT DD SYSOUT=*
//SYSLMOD  DD DSN=LOAD.LIBRARY(MYPROG),DISP=SHR
//SYSUT1   DD UNIT=SYSDA,SPACE=(CYL,(1,1))
//SYSLIN   DD DSN=OBJECT.LIBRARY(MYPROG),DISP=SHR
//         DD *
  NAME MYPROG(R)
/*

//SORTJOB  JOB (ACCT),'SORT DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=SORT
//SYSOUT   DD SYSOUT=*
//SORTIN   DD DSN=INPUT.DATA,DISP=SHR
//SORTOUT  DD DSN=SORTED.DATA,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,
//            SPACE=(CYL,(10,5),RLSE)
//SYSIN    DD *
  SORT FIELDS=(1,10,CH,A)
/*

//TSOBATCH JOB (ACCT),'TSO BATCH',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01
//SYSPRINT DD SYSOUT=*
//SYSTSPRT DD SYSOUT=*
//SYSTSIN  DD *
  LISTCAT ENTRIES('SYS1.PARMLIB') ALL
  LISTDS 'SYS1.PROCLIB' MEMBERS
/*

//LISTCAT  JOB (ACCT),'LISTCAT',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  LISTCAT ENTRIES(MY.DATASET.**) ALL
/*

//REPRO    JOB (ACCT),'REPRO DATA',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//INFILE   DD DSN=SOURCE.DATA,DISP=SHR
//OUTFILE  DD DSN=TARGET.VSAM.KSDS,DISP=SHR
//SYSIN    DD *
  REPRO INFILE(INFILE) OUTFILE(OUTFILE)
/*

//DB2BATCH JOB (ACCT),'DB2 PROGRAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IKJEFT01,DYNAMNBR=20
//STEPLIB  DD DSN=DB2.SDSNLOAD,DISP=SHR
//SYSTSPRT DD SYSOUT=*
//SYSPRINT DD SYSOUT=*
//SYSTSIN  DD *
  DSN SYSTEM(DB2P)
  RUN PROGRAM(MYPROG) PLAN(MYPLAN)
  END
/*

//DEFGDG   JOB (ACCT),'DEFINE GDG',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE GDG (NAME(MY.GDG.BASE) -
              LIMIT(10) -
              NOEMPTY -
              SCRATCH)
/*

//COPYMBR  JOB (ACCT),'COPY MEMBERS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBCOPY
//SYSPRINT DD SYSOUT=*
//INDD     DD DSN=SOURCE.PDS,DISP=SHR
//OUTDD    DD DSN=TARGET.PDS,DISP=SHR
//SYSIN    DD *
  COPY OUTDD=OUTDD,INDD=INDD
  SELECT MEMBER=(MEM1,MEM2,MEM3)
/*

//DELds    JOB (ACCT),'DELETE DS',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEFBR14
//DELDD    DD DSN=OLD.DATASET.TO.DELETE,
//            DISP=(MOD,DELETE,DELETE)

//NEWGEN   JOB (ACCT),'NEW GDG GEN',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IEBGENER
//SYSPRINT DD SYSOUT=*
//SYSUT1   DD DSN=INPUT.DATA,DISP=SHR
//SYSUT2   DD DSN=MY.GDG.BASE(+1),
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,
//            SPACE=(CYL,(5,2),RLSE),
//            DCB=(RECFM=FB,LRECL=80,BLKSIZE=27920)
//SYSIN    DD DUMMY

//MULTISTP JOB (ACCT),'MULTI STEP',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=PROG1
//SYSPRINT DD SYSOUT=*
//INPUT    DD DSN=INPUT.DATA,DISP=SHR
//OUTPUT   DD DSN=&&TEMP1,DISP=(NEW,PASS),
//            UNIT=SYSDA,SPACE=(TRK,(5,2))
//*
//STEP2    EXEC PGM=PROG2,COND=(4,LT,STEP1)
//SYSPRINT DD SYSOUT=*
//INPUT    DD DSN=&&TEMP1,DISP=(OLD,DELETE)
//OUTPUT   DD DSN=FINAL.OUTPUT,
//            DISP=(NEW,CATLG,DELETE),
//            UNIT=SYSDA,SPACE=(CYL,(5,2))

//IEFBR14  JOB (ACCT),'IEFBR14',CLASS=A,MSGCLASS=X,
//             NOTIFY=&SYSUID
//STEP1    EXEC PGM=IEFBR14

//DEFVSAM  JOB (ACCT),'DEFINE VSAM',CLASS=A,MSGCLASS=X
//STEP1    EXEC PGM=IDCAMS
//SYSPRINT DD SYSOUT=*
//SYSIN    DD *
  DEFINE CLUSTER (NAME(MY.VSAM.KSDS) -
                  INDEXED -
                  KEYS(10 0) -
                  RECORDSIZE(100 500) -
                  CYLINDERS(5 2) -
                  SHAREOPTIONS(2 3)) -
         DATA (NAME(MY.VSAM.KSDS.DATA)) -
         INDEX (NAME(MY.VSAM.KSDS.INDEX))
/*

//PROCJOB  JOB (ACCT),'PROC EXAMPLE',CLASS=A,MSGCLASS=X
//         SET DSN=MY.INPUT.DATA
//         SET OUTDSN=MY.OUTPUT.DATA
//STEP1    EXEC MYPROC,INDSN=&DSN,OUTDSN=&OUTDSN
